function venueFallbackDataUrl(sportKey){
 const fill='#e4eee7';
 return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 520"><rect width="800" height="520" fill="${fill}"/><circle cx="650" cy="105" r="150" fill="#d6e4da"/><circle cx="130" cy="420" r="190" fill="#dce9df"/></svg>`);
}
function venueImage(v){
 const primary=mediaUrl(v.image||'');
 return primary || mediaUrl(SPORT_COVERS[v.sportKey]||SPORT_COVERS.fitness);
}

function venueImageError(img,sportKey){
 const fallback=mediaUrl(SPORT_COVERS[sportKey]||SPORT_COVERS.fitness);
 if(!img.dataset.fallback && img.src!==fallback){img.dataset.fallback='1';img.src=fallback;return}
 const parent=img.parentElement;
 img.remove();
 if(parent)parent.classList.add('image-error');
}

function venueImageHtml(v, cls=''){
 const src=venueImage(v);
 const label=(sportLabel(v.sportKey)||v.sport||'Sporta vieta').toUpperCase();
 return `<div class="venue-media ${cls}"><div class="venue-photo-placeholder"><span>${sportIcon(v.sportKey,26)}</span><small>${esc(label)}</small></div><img src="${esc(src)}" alt="${esc(v.name)}" loading="lazy" decoding="async" referrerpolicy="no-referrer" onload="this.parentElement.classList.add('has-image')" onerror="venueImageError(this,'${esc(v.sportKey)}')"></div>`;
}

function migrateCart(c){
  if(!Array.isArray(c)) return [];
  return c.map(x=>{
    let id=x.id||PRODUCTS[x.idx]?.id;
    if(id==='ccm-tacks-as580-stick') id='ccm-tacks-as580-skates';
    return {id,qty:Math.max(1,Number(x.qty??x.quantity??1))};
  }).filter(x=>PRODUCTS.some(p=>p.id===x.id));
}
function productById(id){return PRODUCTS.find(p=>p.id===id)}

