 if(k==='pickleball') return `<span class="sport-glyph sport-svg" style="width:${size}px;height:${size}px" role="img" aria-label="${esc(label)}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5.3 3.9c3.6-1.6 7.6.1 8.4 3.5.7 3-1 5.9-4.2 7.1l4.4 6.1-2.2 1.2-4.8-6.7c-2.1-.6-3.8-2.2-4.4-4.1-.8-2.7.3-5.8 2.8-7.1Z" fill="currentColor"/><circle cx="17.8" cy="7.3" r="3.5" fill="currentColor"/><circle cx="16.6" cy="6.3" r=".55" fill="#fff"/><circle cx="18.8" cy="6.1" r=".55" fill="#fff"/><circle cx="19.2" cy="8.2" r=".55" fill="#fff"/></svg></span>`;
