 const c={Wilson:'#8f3412',Head:'#2f4a3a',Adidas:'#201d17',Babolat:'#8f3412',Spalding:'#8f3412',Bauer:'#42657d',CCM:'#233a45',Mikasa:'#2f4a3a',Venum:'#6e2520',Everlast:'#4b2b22',Speedo:'#18596c',Arena:'#18596c',Nike:'#201d17',Garmin:'#18596c',Trek:'#b5451c',Giro:'#2f4a3a',Casall:'#5c4334',Innova:'#a8791f',Discraft:'#b5451c'}[brand]||'#3d372d';
